package main

import (
	"bytes"
	"encoding/binary"
	"net"
	"net/netip"
	"testing"
	"time"

	"go.peanball.net/cap/internal/engine"
	"go.peanball.net/cap/internal/match"
	"go.peanball.net/cap/internal/pcap"
	"go.peanball.net/cap/internal/testgenpcap"
)

// Tunnel scenarios live in cmd/cap/testdata/*.pcap (generated by
// `go run ./test`, drift-pinned by internal/testgenpcap). Open them in
// Wireshark to see the outer/inner headers the tests below assert on.

// TestTunneledSNIMatch verifies the matcher chain sees the INNER stream's
// SNI for tunneled traffic (testdata/tunnel_sni.pcap).
func TestTunneledSNIMatch(t *testing.T) {
	records := loadFixture(t, "tunnel_sni.pcap")

	var outBuf bytes.Buffer
	wr := pcap.NewWriterRaw(&outBuf, pcap.LinkEthernet, 65535, false, pcap.FormatClassic)
	m, err := match.NewSNI([]string{"target.example.com"})
	if err != nil {
		t.Fatalf("NewSNI: %v", err)
	}
	eng, err := engine.New(engine.Config{Matcher: m}, wr)
	if err != nil {
		t.Fatalf("engine.New: %v", err)
	}
	for _, r := range records {
		if err := eng.Process(pcap.LinkEthernet, r.Timestamp, r.Data); err != nil {
			t.Fatalf("Process: %v", err)
		}
	}
	eng.Close()

	rdr, _ := pcap.NewReader(bytes.NewReader(outBuf.Bytes()))
	kept := 0
	// ethLen past the Ethernet header; the EtherType word sits in its last 2
	// bytes (IEEE 802.3).
	const (
		ethLen          = testgenpcap.EthHdrLen
		etherTypeOffset = ethLen - 2
	)
	for {
		rec, err := rdr.Record()
		if err != nil {
			break
		}
		kept++
		if len(rec.Data) < ethLen+testgenpcap.IPv6HdrLen+testgenpcap.IPv4HdrLen+testgenpcap.TCPHdrLen {
			t.Errorf("kept record too short to be tunneled frame: %d bytes", len(rec.Data))
		}
		// EtherType 0x86dd = IPv6, next-header 4 = inner IPv4 (RFC 2473).
		if et := binary.BigEndian.Uint16(rec.Data[etherTypeOffset:ethLen]); et != 0x86dd {
			t.Errorf("kept record EtherType = 0x%04x, want IPv6 0x86dd", et)
		}
	}
	if kept != 4 {
		t.Errorf("kept %d records, want 4 (whole tunneled stream)", kept)
	}
}

// TestTunnelIPGate verifies --tunnel-ip filters on OUTER tunnel endpoints:
// of the two streams in testdata/tunnel_ip_gate.pcap, only the one whose
// outer 6-tuple matches the CIDR is kept.
func TestTunnelIPGate(t *testing.T) {
	records := loadFixture(t, "tunnel_ip_gate.pcap")

	var outBuf bytes.Buffer
	wr := pcap.NewWriterRaw(&outBuf, pcap.LinkEthernet, 65535, false, pcap.FormatClassic)

	cidr := netip.MustParsePrefix("2001:db8::/48")
	tunnelKM := match.NewTunnelIP([]netip.Prefix{cidr})
	sniM, _ := match.NewSNI([]string{"target.example.com"})

	eng, err := engine.New(engine.Config{
		Matcher:     sniM,
		KeyMatchers: []match.KeyMatcher{tunnelKM},
	}, wr)
	if err != nil {
		t.Fatalf("engine.New: %v", err)
	}
	for _, r := range records {
		if err := eng.Process(pcap.LinkEthernet, r.Timestamp, r.Data); err != nil {
			t.Fatalf("Process: %v", err)
		}
	}
	eng.Close()

	rdr, _ := pcap.NewReader(bytes.NewReader(outBuf.Bytes()))
	kept := 0
	// ethLen past Ethernet; IPv6 src/dst are the 16-byte fields at +8 and +24
	// into the IPv6 header (RFC 8200).
	const ethLen = testgenpcap.EthHdrLen
	for {
		rec, err := rdr.Record()
		if err != nil {
			break
		}
		kept++
		if len(rec.Data) < ethLen+testgenpcap.IPv6HdrLen {
			t.Fatal("kept record short")
		}
		v6src := net.IP(rec.Data[ethLen+8 : ethLen+24]).String()
		if v6src != "2001:db8::1" {
			t.Errorf("kept record with tunnel src %s (should be only allowed tunnel)", v6src)
		}
	}
	if kept != 3 {
		t.Errorf("kept %d, want 3 (allowed tunnel stream only)", kept)
	}
}

// TestPlainStreamRejectedByTunnelKey verifies non-tunneled streams fail
// tunnel key matchers by default ("gate on tunneled").
func TestPlainStreamRejectedByTunnelKey(t *testing.T) {
	srcMAC := []byte{0x00, 0x11, 0x22, 0x33, 0x44, 0x55}
	dstMAC := []byte{0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb}

	data := eth(srcMAC, dstMAC,
		net.ParseIP("10.0.0.1"), net.ParseIP("93.184.216.34"),
		50001, 443, 1000, 1, 0x02, nil)

	var outBuf bytes.Buffer
	wr := pcap.NewWriterRaw(&outBuf, pcap.LinkEthernet, 65535, false, pcap.FormatClassic)

	cidr := netip.MustParsePrefix("2001:db8::/32")
	tunnelKM := match.NewTunnelIP([]netip.Prefix{cidr})

	eng, err := engine.New(engine.Config{
		KeyMatchers: []match.KeyMatcher{tunnelKM},
	}, wr)
	if err != nil {
		t.Fatalf("engine.New: %v", err)
	}
	if err := eng.Process(pcap.LinkEthernet, time.Now(), data); err != nil {
		t.Fatalf("Process: %v", err)
	}
	eng.Close()

	rdr, _ := pcap.NewReader(bytes.NewReader(outBuf.Bytes()))
	if _, err := rdr.Record(); err == nil {
		t.Errorf("plain stream leaked through tunnel-key gate")
	}
}
